<script setup lang="ts">
import {computed,ref,watch,onUnmounted,nextTick} from 'vue';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';import {useSourceMedia,type MediaScope} from './useSourceMedia';
const props=defineProps<{scope:MediaScope|null;active:boolean}>();const {session,transcripts}=useApplication();const state=useSourceMedia((...args)=>transcripts.source(...args),()=>session.current.value?.actor.enterpriseId??null,()=>props.active?props.scope:null);
const element=ref<HTMLMediaElement>(),current=ref(0),duration=ref(0),playing=ref(false),speed=ref(1),localError=ref<string|null>(null);const video=computed(()=>state.type.value.startsWith('video/'));
function clock(seconds:number){const n=Math.max(0,Math.floor(seconds));return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n/60)%60).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function update(){const m=element.value;if(!m)return;current.value=m.currentTime;duration.value=Number.isFinite(m.duration)?m.duration:0;playing.value=!m.paused;speed.value=m.playbackRate;}
function failure(){playing.value=false;localError.value='当前浏览器无法播放此编码；可继续处理文件';}
async function toggle(){const m=element.value;if(!m)return;localError.value=null;if(m.paused){try{await m.play();}catch{failure();}}else m.pause();}
function rate(){const m=element.value;if(!m)return;const speeds=[1,1.25,1.5,2];m.playbackRate=speeds[(speeds.indexOf(m.playbackRate)+1)%speeds.length]??1;update();}
function jump(seconds:number){const m=element.value;if(m&&Number.isFinite(m.duration)){m.currentTime=Math.min(m.duration,Math.max(0,seconds));update();}}
function slider(event:MouseEvent){const box=(event.currentTarget as HTMLElement).getBoundingClientRect();if(box.width)jump(duration.value*Math.max(0,Math.min(1,(event.clientX-box.left)/box.width)));}
let pendingSeek:{file:string;seconds:number}|null=null;
function metadata(){update();if(pendingSeek?.file===state.selected.value){jump(pendingSeek.seconds);pendingSeek=null;}}
async function seek(file:string,startMs:number){if(!Number.isSafeInteger(startMs)||startMs<0||!state.sources.value.some(s=>s.fileId===file))return;pendingSeek={file,seconds:startMs/1000};if(state.selected.value===file&&state.url.value){metadata();return;}await state.select(file);await nextTick();if(element.value?.readyState)metadata();}
watch(state.url,()=>{element.value?.pause();current.value=0;duration.value=0;playing.value=false;speed.value=1;localError.value=null;},{flush:'sync'});watch(()=>props.active,active=>{if(!active)element.value?.pause();});const logout=session.onLogout(()=>{element.value?.pause();state.dispose();});onUnmounted(()=>{logout();element.value?.pause();});defineExpose({seek});
</script>
<template>
 <div v-if="!state.sources.value.length" class="card card-p"><b>会议录音</b><div class="small muted mt12">本次为文本转写文件，无原录音，不虚构播放时长。</div></div>
 <div v-else class="aci-player-list"><div class="player"><div class="p-top"><Icon :name="video?'play':'mic'" :size="14"/> {{video?'会议视频':'会议录音'}}<span class="aci-source-count">{{state.sources.value.findIndex(s=>s.fileId===state.selected.value)+1}} / {{state.sources.value.length}}</span></div><div class="aci-playing-name" :title="state.name.value??''">{{state.name.value??(state.busy.value?'正在读取原文件…':'会议录音')}}</div>
  <video v-if="video&&state.url.value" ref="element" :key="state.url.value" class="aci-video" :src="state.url.value" preload="metadata" playsinline @loadedmetadata="metadata" @durationchange="update" @timeupdate="update" @play="update" @pause="update" @ended="update" @error="failure"/>
  <audio v-else-if="state.url.value" ref="element" :key="state.url.value" :src="state.url.value" preload="metadata" @loadedmetadata="metadata" @durationchange="update" @timeupdate="update" @play="update" @pause="update" @ended="update" @error="failure"/>
  <div class="p-main"><button class="p-btn" :disabled="!state.url.value||state.busy.value" aria-label="播放或暂停录音" @click="toggle"><Icon :name="playing?'pause':'play'" :size="16"/></button><div class="p-progress" role="slider" tabindex="0" aria-label="播放进度" :aria-valuemin="0" :aria-valuemax="Math.floor(duration)" :aria-valuenow="Math.floor(current)" @click="slider" @keydown.left.prevent="jump(current-5)" @keydown.right.prevent="jump(current+5)" @keydown.home.prevent="jump(0)" @keydown.end.prevent="jump(duration)"><div class="p-track"><div class="p-fill" :style="{width:(duration?current/duration*100:0)+'%'}"></div></div></div><button class="p-speed" :disabled="!state.url.value" @click="rate">{{speed}}x</button></div><div class="aci-media-time"><span>{{clock(current)}}</span><span>{{duration?clock(duration):'时长加载中'}}</span></div><div v-if="state.error.value||localError" class="ac-error small" role="alert">{{state.error.value??localError}} <button v-if="state.error.value" class="btn sm" @click="state.selected.value&&state.select(state.selected.value)">重试</button></div>
 </div><div class="aci-file-playlist"><button v-for="(source,index) in state.sources.value" :key="source.fileId" class="aci-playlist-row" :class="{active:state.selected.value===source.fileId}" :disabled="state.busy.value" @click="state.select(source.fileId)"><span>{{String(index+1).padStart(2,'0')}}</span><span>{{state.names.value[source.fileId]??'会议录音 '+(index+1)}}</span><small>{{state.selected.value===source.fileId&&duration?clock(duration):'--'}}</small></button></div></div>
</template>
